el=(data,collection,id)=>data[collection].find(option=>option.id===id)?.label||id;\nexport const number=(value,maximumFractionDigits=2)=>new Intl.NumberFormat('en-GB',{maximumFractionDigits}).format(value);\n\nexport function specification(state,data,countries,unit='metric') {\n  const d=dimensions(state,data),pricing=calculatePricing(state,data),length=value=>formatLength(value,unit);\n  const commercial=commercialTerms(state,data,pricing);\n  const country=countries.find(country=>country.code===state.country)?.name||'Not selected';\n  return {dimensions:d,pricing,flags:reviewFlags(state,data),rows:[\n    ['Screen',data.geometries[state.geometry].label],\n    ['Curvature diameter',length(state.diameter)],\n    ['Horizontal field of view',`${number(state.horizontalFov)}°`],\n    ['Viewable screen height',length(d.viewableHeight)],\n    [state.geometry==='curved'?'Overall height including supports':'Top of screen above floor (preview)',length(d.overallHeight)],\n    ['Upper coverage',state.geometry==='hemispherical'?`${number(state.upperCoverage)}% (${number(state.upperCoverage*.9)}° above horizon)`:'Not applicable'],\n    ['Lower coverage',state.geometry==='hemispherical'?`${number(state.lowerCoverage)}% (${number(state.lowerCoverage*.9)}° below horizon)`:'Not applicable'],\n    ['Active screen surface',`${formatArea(d.area,unit)} (${d.moduleLayout?'whole-module area':'geometric estimate'})`],\n    ['Module layout',d.moduleLayout?`${d.moduleLayout.columns} columns × ${d.moduleLayout.rows} rows = ${d.moduleLayout.moduleCount} modules · ${number(d.moduleLayout.moduleWidth*1000)} × ${number(d.moduleLayout.moduleHeight*1000)} mm landscape`:'Custom-made hemispherical system'],\n    ['Width around curve',length(d.arcLength)],\n    ['Lowest edge above floor',length(state.geometry==='hemispherical'?state.screenClearance:d.supportHeight)],\n    ['Custom metal support frame',commercial.frame||'Final structural design to confirm'],\n    ['Estimated production lead time',commercial.leadTime+' — '+commercial.leadTimeNote],\n    ['Payment terms',commercial.payment],\n    ...(commercial.upfrontAmount===null?[]:[['Payment at order (provisional)',`${commercial.upfrontPercent}% · ${state.currency} ${number(commercial.upfrontAmount)}`]]),\n    ['Pixel pitch',optionLabel(data,'pixelPitches',state.pixelPitch)],\n    ...(pricing.costReview?pricing.lineItems.filter(item=>['screen','spares'].includes(item.id)&&item.amount!==null&&item.unitAmount!==null).map(item=>[item.id==='screen'?'Screen supplier-cost calculation':'Spare supplier-cost calculation',`${item.quantity} modules × ${pricing.baseCurrency} ${number(item.baseUnitAmount??item.unitAmount)} = ${pricing.baseCurrency} ${number(item.baseAmount??item.amount)}${state.currency!==pricing.baseCurrency?' ≈ '+state.currency+' '+number(item.amount):''}`]):[]),\n    ['System controller',optionLabel(data,'hardwarePackages',state.hardware)],\n    ['Spare components',`${state.spares==='custom'?number(state.customSpares):state.spares}%${state.spares==='custom'?' — custom request':''}`],\n    ['Spare LED modules',pricing.spareModules!==null?`${pricing.spareModules} whole modules`:'Confirmed with quotation'],\n    ['Warranty',optionLabel(data,'warranties',state.warranty)],\n    ['Installation',optionLabel(data,'installations',state.installation)],\n    ['Preconfigured warp file',optionLabel(data,'warpFiles',state.warpFile)],\n    ['Warp / calibration software',optionLabel(data,'warpSoftware',state.warpSoftware)],\n    ['Application',optionLabel(data,'applications',state.application)||'Not selected'],\n    ['Installation country',country],\n    ['Aircraft / vehicle / simulator',state.cockpit||'Not specified'],\n    ['Display currency',state.currency],\n    ...(pricing.exchangeRate&&state.currency!==pricing.baseCurrency?[[\"Indicative currency conversion\",`1 ${pricing.baseCurrency} = ${pricing.exchangeRate} ${state.currency} · reference ${pricing.exchangeRateDate||'to confirm'}`]]:[]),\n    ['Simulator reference',`${optionLabel(data,'simulatorReferences',state.simulatorType)} · ${state.showSimulator?'shown':'hidden (settings retained)'}`],\n    ['Reference width × depth × height',`${length(state.simulatorWidth)} × ${length(state.simulatorDepth)} × ${length(state.simulatorHeight)}`],\n    ['Cockpit base height above floor',length(state.simulatorY??0)],\n    ['Reference position / turn',`${length(state.simulatorX)} left/right · ${length(state.simulatorZ)} forward/back · ${number(state.simulatorYaw)}°`]\n  ]};\n}\n\nexport function quoteMessage(state,data,countries,customer) {\n  const spec=specification(state,data,countries);\n  return ['SIMWORX LED VISUAL SYSTEM — REQUEST FOR QUOTE','',\n    ...spec.rows.map(([label,value])=>`${label}: ${value}`),'',\n    'CUSTOM REQUIREMENTS',state.customRequirements||'None supplied','',\n    spec.pricing.costReview?'SUPPLIER COST REVIEW — NO MARKUP':spec.pricing.hasSampleOptions?'TEST ESTIMATE — SCREEN RATES WITH SAMPLE OPTIONS':spec.pricing.isDemo?'SAMPLE PRICE — DEMO RATES':'INDICATIVE PRICE',spec.pricing.total===null?spec.pricing.status:`${state.currency} ${number(spec.pricing.total)} — ${spec.pricing.status}`,\n    spec.pricing.disclaimer,\n    ...spec.pricing.exclusions,'','TECHNICAL REVIEW',...spec.flags,'',\n    'PROJECT / CUSTOMER COMMENTS',customer.project||'Project name not supplied',customer.comments||'No additional comments'\n  ].join('\\n');\n}\n\n/** Short customer-facing quote; raw calculation/provenance stays in the engine. */\nexport function quotePresentation(pricing,currency){\n  const money=value=>new Intl.NumberFormat('en-GB',{style:'currency',currency,minimumFractionDigits:2,maximumFractionDigits:2}).format(value);\n  const terms=['Excludes taxes, freight, installation travel and accommodation.','Geometry, equipment compatibility and final scope are subject to Simworx technical review.'];\n  if(pricing.hasSampleOptions||pricing.isDemo)terms.unshift('Provisional prices: equipment and service amounts are development figures pending confirmation.');\n  if(pricing.costReview)terms.push('LED screen and spares use whole-module supplier costs with no markup; supplier validation is pending.');\n  if(pricing.exchangeRate&&currency!==pricing.baseCurrency)terms.push(`Indicative exchange rate: 1 ${pricing.baseCurrency} = ${pricing.exchangeRate} ${currency} (${pricing.exchangeRateDate||'reference date to confirm'}).`);\n  const lines=pricing.lineItems.map(item=>[item.label.replace(' (sample)',' (provisional)')+(item.quantity!==null&&item.quantity!==undefined?` · ${item.quantity} modules`:''),item.notRequested?'Not selected':item.amount===null?(item.id==='customFrame'?'POA':'Price to confirm'):item.amount===0?'Included':money(item.amount)]);\n  lines.push(['Quote total',pricing.total===null?'Price to confirm':money(pricing.total)]);\n  return {total:pricing.total===null?'Price to confirm':money(pricing.total),lines,terms,note:pricing.quoteOnly?'Custom-made system. Price follows technical review.':pricing.total===null?'Selected items require pricing or technical review.':pricing.hasSampleOptions||pricing.isDemo?'Provisional quote · excludes tax and delivery.':'Excludes tax and delivery. Subject to technical review.'};\n}\n", "quoteActions": "export function loadQuoteProtection(){\n  if(document.documentElement.dataset.ledQuotePreview==='offline'||window.SimworxLEDProtectionLoaded)return;\n  window.SimworxLEDProtectionLoaded=true;\n  if(window.SimworxLEDLoadProtection){window.SimworxLEDLoadProtection();return;}\n  const script=document.createElement('script');script.src='assets/js/form-protection.js';\n  script.onerror=()=>{window.SimworxLEDProtectionLoaded=false;};document.head.append(script);\n}\n/** Email-gated quote actions. Newsletter consent is always a separate, unticked choice. */\nexport function createQuoteActions({form,getConfiguration,getCustomer,onSave,captureViews=async()=>[]}){\n  const byId=id=>document.getElementById(id),dialog=byId('led-quote-dialog'),submit=byId('led-request-button');\n  const status=byId('led-submission-status'),result=byId('led-action-result'),printAgain=byId('led-print-again');\n  let action='print',busy=false,protectionLoaded=false,opener;\n  const labels={print:'Continue to Print Quote',email:'Email me Quote',contact:'Ask Simworx to contact me'};\n  const titles={print:'Print your quote',email:'Email your quote',contact:'Discuss your quote with Simworx'};\n  const describe={print:'Enter your email address to print or save your configured quote.',email:'Enter your email address and we will send your configured quote.',contact:'Tell us how to reach you. Your quote and full specification will be included.'};\n  function setStatus(text,error=false){status.textContent=text;status.classList.toggle('led-action-error',error);}\n  function close(){if(!busy){dialog.close();opener?.focus();}}\n  for(const button of document.querySelectorAll('[data-quote-action]')){\n    button.disabled=false;\n    button.addEventListener('click',()=>{\n      opener=button;action=button.dataset.quoteAction;byId('led-dialog-title').textContent=titles[action];byId('led-dialog-description').textContent=describe[action];\n      byId('led-contact-fields').hidden=action!=='contact';form.elements.name.required=action==='contact';\n      byId('led-newsletter').checked=false;byId('led-quote-action').value=action;submit.textContent=labels[action];submit.disabled=false;setStatus('');\n      dialog.showModal();form.elements.email.focus();loadQuoteProtection();\n    });\n  }\n  byId('led-dialog-close').addEventListener('click',close);\n  dialog.addEventListener('cancel',event=>{event.preventDefault();close();});\n  dialog.addEventListener('click',event=>{if(event.target===dialog){const b=dialog.getBoundingClientRect();if(event.clientX\u003cb.left||event.clientX>b.right||event.clientY\u003cb.top||event.clientY>b.bottom)close();}});\n  printAgain.addEventListener('click',()=>window.print());\n  form.addEventListener('submit',async event=>{\n    event.preventDefault();if(busy||!form.reportValidity())return;\n    if(document.documentElement.dataset.ledQuotePreview==='offline'){setStatus('Email and contact sending require the hosted review page.',true);return;}\n    busy=true;submit.disabled=true;byId('led-dialog-close').disabled=true;setStatus('Preparing your configuration views…');\n    const payload=new FormData(form);const images=await captureViews().catch(()=>[]);payload.set('led_images',JSON.stringify(images));payload.set('led_configuration',JSON.stringify(getConfiguration()));payload.set('quote_action',action);payload.set('length_unit',document.getElementById('led-dimension-unit')?.value||'metric');\n    payload.set('newsletter',byId('led-newsletter').checked?'yes':'no');payload.set('consent_version','led-updates-v1');\n    busy=true;submit.disabled=true;byId('led-dialog-close').disabled=true;setStatus(action==='print'?'Preparing your quote…':'Sending…');onSave();\n    const locked=[...form.querySelectorAll('input,textarea,select')].filter(input=>!input.disabled);locked.forEach(input=>input.disabled=true);\n    try{\n      const response=await fetch(form.action,{method:'POST',body:payload,headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});\n      const reply=await response.json().catch(()=>({ok:false,message:'Your request could not be confirmed. Please try again.'}));\n      if(!response.ok||!reply.ok)throw new Error(reply.message||'Your request could not be completed. Please try again.');\n      if(typeof reply.quote?.html!=='string'||!reply.quote.reference)throw new Error('The quote document could not be confirmed. Please try again.');\n      byId('led-print-document').innerHTML=reply.quote.html;\n      const message=action==='print'?`Quote ${reply.quote.reference} is ready to print.`:action==='email'?`Quote ${reply.quote.reference} has been sent to ${getCustomer().email}.`:`Simworx has received quote ${reply.quote.reference} and your contact request.`;\n      result.textContent=message;printAgain.hidden=false;busy=false;dialog.close();opener?.focus();\n      if(action==='print')window.print();\n    }catch(error){setStatus(error.message||'Unable to send. Please email info@sim-worx.com.',true);}\n    finally{locked.forEach(input=>input.disabled=false);busy=false;submit.disabled=false;byId('led-dialog-close').disabled=false;submit.textContent=labels[action];form.dispatchEvent(new Event('simworx:submission-complete'));}\n  });\n  return {invalidate(){printAgain.hidden=true;result.textContent='';byId('led-print-document').replaceChildren();}};\n}\n", "profiles": "import {loadQuoteProtection} from './quote-actions.js?v=16';\n\n/** Passwordless sign-in; the server keeps profile data outside the web root. */\nexport function createProfiles({getConfiguration,getUnit,getCustomer,onRestore,defaultSimulator}){\n  const byId=id=>document.getElementById(id),dialog=byId('led-profile-dialog'),form=byId('led-profile-form'),submit=byId('led-profile-submit'),status=byId('led-profile-status'),message=byId('led-profile-message');\n  let mode='save',profile=null,busy=false,opener;\n  async function request(payload){\n    const response=await fetch(form.action,{method:'POST',body:payload,headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});\n    const result=await response.json().catch(()=>({ok:false,message:'Your profile request could not be confirmed. Please try again.'}));\n    if(!response.ok||!result.ok)throw new Error(result.message||'Your profile request could not be completed. Please try again.');\n    return result;\n  }\n  function data(action){const payload=new FormData();payload.set('quote_action',action);return payload;}\n  function updateProfile(next,restore=false){\n    profile=next;status.textContent=profile?`Signed in as ${profile.username}`:'';byId('led-profile-logout').hidden=!profile;byId('led-profile-login').hidden=!!profile;\n    if(profile&&restore)onRestore(profile);\n  }\n  function open(kind,button){\n    opener=button;mode=kind;const save=kind==='save';byId('led-profile-fields').hidden=!save;\n    for(const input of byId('led-profile-fields').querySelectorAll('input,select'))input.disabled=!save;\n    byId('led-profile-title').textContent=save?'Save your profile':'Sign in to your profile';\n    byId('led-profile-description').textContent=save?'Save your current screen, cockpit, options and units. Return through a secure email sign-in link.':'Enter your email to receive a secure sign-in link and restore your saved configuration.';\n    submit.textContent=save?(profile?'Save profile & configuration':'Save & email sign-in link'):'Email me a sign-in link';message.textContent='';\n    const c=getCustomer();form.elements.email.value=profile?.email||c.email||'';\n    if(save){form.elements.username.value=profile?.username||c.name||'';form.elements.organisation.value=profile?.company||c.organisation||'';form.elements.profile_location.value=profile?.location||'';form.elements.profile_simulator.value=profile?.simulatorType||defaultSimulator();form.elements.profile_role.value=profile?.role||'';byId('led-profile-newsletter').checked=false;}\n    dialog.showModal();form.elements.email.focus();loadQuoteProtection();\n  }\n  for(const [id,kind] of [['led-save-profile','save'],['led-profile-login','login']]){const button=byId(id);button.disabled=false;button.addEventListener('click',()=>open(kind,button));}\n  function close(){if(!busy){dialog.close();opener?.focus();}}\n  byId('led-profile-close').addEventListener('click',close);dialog.addEventListener('cancel',event=>{event.preventDefault();close();});\n  byId('led-profile-logout').addEventListener('click',async()=>{try{await request(data('profile-logout'));updateProfile(null);status.textContent='Signed out. Your current configuration stays on this page.';}catch(error){status.textContent=error.message;}});\n  form.addEventListener('submit',async event=>{\n    event.preventDefault();if(busy||!form.reportValidity())return;\n    const payload=new FormData(form);payload.set('quote_action','profile-'+mode);\n    if(mode==='save'){payload.set('led_configuration',JSON.stringify(getConfiguration()));payload.set('length_unit',getUnit());payload.set('newsletter',byId('led-profile-newsletter').checked?'yes':'no');payload.set('consent_version','led-updates-v1');}\n    busy=true;submit.disabled=true;byId('led-profile-close').disabled=true;message.textContent=mode==='save'?'Saving your profile…':'Sending your sign-in link…';\n    try{const result=await request(payload);if(result.profile)updateProfile(result.profile);message.textContent=result.message;status.textContent=result.message;}\n    catch(error){message.textContent=error.message;}\n    finally{busy=false;submit.disabled=false;byId('led-profile-close').disabled=false;form.dispatchEvent(new Event('simworx:submission-complete'));}\n  });\n  // The token stays in the fragment (not server URLs/referrers); consume it once.\n  async function initialise(){\n    if(document.documentElement.dataset.ledQuotePreview==='offline')return;\n    const match=location.hash.match(/^#profile=([a-f0-9]{64})$/);\n    if(match){history.replaceState(null,'',location.pathname+location.search);const payload=data('profile-redeem');payload.set('token',match[1]);\n      try{const result=await request(payload);updateProfile(result.profile,true);status.textContent=`Welcome ${result.profile.username}. Your saved configuration is restored.`;}\n      catch(error){status.textContent=error.message;}\n    }else{\n      try{const result=await request(data('profile-current'));updateProfile(result.profile,!sessionStorage.getItem('simworxLedQuoteV1')&&!sessionStorage.getItem('simworxLedOfflinePreviewV1'));}catch{/* The configurator continues working if profile storage is unavailable. */}\n    }\n  }\n  window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#profile='))initialise();});\n  initialise();return {current:()=>profile};\n}\n", "units": "// Presentation only. Geometry, module snapping and supplier pricing always use metres.\nexport const lengthKeys=new Set(['diameter','viewableHeight','overallHeight','screenClearance','simulatorWidth','simulatorDepth','simulatorHeight','simulatorX','simulatorY','simulatorZ']);\nexport const lengthFactor=unit=>unit==='imperial'?1/.3048:1;\nexport const lengthSymbol=unit=>unit==='imperial'?'ft':'m';\nexport const formatLength=(value,unit='metric')=>`${new Intl.NumberFormat('en-GB',{maximumFractionDigits:2}).format(value*lengthFactor(unit))} ${lengthSymbol(unit)}`;\nexport const formatArea=(value,unit='metric')=>`${new Intl.NumberFormat('en-GB',{maximumFractionDigits:4}).format(value*lengthFactor(unit)**2)} ${lengthSymbol(unit)}²`;\n", "commercial": "/** Approved buying terms are catalogue data; display currency never changes the policy. */\nexport function commercialTerms(state,data,pricing){\n  const supply=data.geometries[state.geometry].supply;\n  const policy=data.buyerGuide.payment;\n  let payment='50% to start the order; the balance before shipping. Smaller screen orders require 100% upfront. Your payment schedule is confirmed with the formal quotation.';\n  let upfrontPercent=null,upfrontAmount=null;\n  if(policy.thresholdCurrency&&policy.thresholdBasis){\n    const rate=data.pricing.exchangeRates[policy.thresholdCurrency];\n    const source=policy.thresholdBasis==='screen'?pricing.screenSubtotal:pricing.total;\n    const displayRate=data.pricing.exchangeRates[state.currency];\n    const baseLines=policy.thresholdBasis==='screen'?pricing.lineItems.filter(item=>item.id==='screen'):pricing.lineItems;\n    const baseKnown=baseLines?.length&&baseLines.every(item=>typeof item.baseAmount==='number'&&Number.isFinite(item.baseAmount));\n    const value=source===null?null:baseKnown&&rate>0?Math.round(baseLines.reduce((sum,item)=>sum+(pricing.costReview?Math.round(item.baseAmount*rate*100)/100:item.baseAmount*rate),0)*100)/100:rate>0&&displayRate>0?source/displayRate*rate:null;\n    const threshold=new Intl.NumberFormat('en-GB',{style:'currency',currency:policy.thresholdCurrency,maximumFractionDigits:0}).format(policy.threshold);\n    const basis=policy.thresholdBasis==='screen'?'LED screen':'complete quote before tax and delivery';\n    payment=`${basis[0].toUpperCase()+basis.slice(1)} below ${threshold}: 100% upfront. Otherwise 50% to start the order; the balance before shipping.`;\n    if(value!==null){upfrontPercent=value\u003cpolicy.threshold?100:50;upfrontAmount=pricing.total===null?null:Math.round(pricing.total*upfrontPercent)/100;}\n  }\n  return {leadTime:supply.leadTimeLabel,leadTimeNote:supply.leadTimeNote,frame:state.geometry==='hemispherical'?'Custom frame required — POA':null,payment,upfrontPercent,upfrontAmount};\n}\n", "buyerHelp": "import {commercialTerms} from './commercial.js?v=16';\n\nconst clean=text=>text.toLowerCase().replace(/[^a-z0-9.% ]/g,' ').replace(/\\b([a-z]{4,})s\\b/g,'$1').replace(/\\s+/g,' ').trim();\nexport function matchBuyerTopics(question,topics){\n  const text=` ${clean(question)} `;\n  return topics.filter(topic=>topic.id!=='unknown').map(topic=>({id:topic.id,score:topic.keywords.reduce((score,keyword)=>score+(text.includes(` ${clean(keyword)} `)?keyword.includes(' ')?3:1:0),0)})).filter(item=>item.score>0).sort((a,b)=>b.score-a.score).slice(0,2).map(item=>item.id);\n}\nexport function buyerAnswer(id,state,data,pricing){\n  const topic=data.buyerGuide.topics.find(topic=>topic.id===id)||data.buyerGuide.topics.find(topic=>topic.id==='unknown');\n  const terms=commercialTerms(state,data,pricing);\n  return {...topic,answer:topic.answer.map(text=>text.replace(/\\{(leadTime|leadTimeNote|payment)\\}/g,(_,key)=>terms[key]))};\n}\n\n/** Guide never changes a selection. All visible answers come from approved catalogue text. */\nexport function createBuyerHelp({data,getState,getPricing,endpoint}){\n  const dialog=document.getElementById('led-buyer-dialog'),comparison=document.getElementById('led-pitch-dialog');\n  const messages=document.getElementById('led-buyer-messages'),stepText=document.getElementById('led-buyer-step');\n  const steps=data.buyerGuide.walkthrough;let step=0,opener=null,busy=false,aiUnavailable=false,mode='Built-in answers';\n  const element=(tag,text,className='')=>{const node=document.createElement(tag);node.textContent=text;if(className)node.className=className;return node;};\n  const answer=id=>buyerAnswer(id,getState(),data,getPricing());\n  function addAnswer(id){\n    const topic=answer(id),block=element('div','','led-buyer-answer');block.append(element('strong',topic.title));\n    topic.answer.forEach(text=>block.append(element('p',text)));\n    if(id==='pitch'){const button=element('button','Which Pixel Pitch?','led-profile-link');button.type='button';button.addEventListener('click',openComparison);block.append(button);}\n    const go=element('button','Show this section','led-button led-outline');go.type='button';go.addEventListener('click',()=>{const target=document.getElementById(topic.target);if(target)opener=target;dialog.close();if(target){target.scrollIntoView({behavior:'auto',block:'center'});target.setAttribute('tabindex','-1');target.focus({preventScroll:true});target.classList.add('led-help-highlight');setTimeout(()=>target.classList.remove('led-help-highlight'),2500);}});block.append(go);messages.append(block);messages.scrollTop=messages.scrollHeight;\n  }\n  function showStep(){messages.replaceChildren();stepText.textContent=`Step ${step+1} of ${steps.length}`;document.getElementById('led-buyer-prev').disabled=step===0;document.getElementById('led-buyer-next').disabled=step===steps.length-1;addAnswer(steps[step]);messages.scrollTop=0;}\n  const show=()=>{opener=document.activeElement;showStep();dialog.showModal();};\n  document.querySelectorAll('[data-buyer-help]').forEach(button=>{button.disabled=false;button.addEventListener('click',show);});\n  dialog.addEventListener('close',()=>{opener?.focus?.({preventScroll:true});});\n  document.getElementById('led-buyer-close').addEventListener('click',()=>dialog.close());\n  document.getElementById('led-buyer-prev').addEventListener('click',()=>{step--;showStep();});\n  document.getElementById('led-buyer-next').addEventListener('click',()=>{step++;showStep();});\n  document.getElementById('led-buyer-restart').addEventListener('click',()=>{step=0;showStep();});\n  const suggestions=document.getElementById('led-buyer-suggestions');\n  for(const id of ['pitch','warp','delivery','payment']){const topic=answer(id),button=element('button',topic.question,'led-buyer-suggestion');button.type='button';button.addEventListener('click',()=>{messages.append(element('p',topic.question,'led-buyer-question'));addAnswer(id);});suggestions.append(button);}\n  document.getElementById('led-buyer-form').addEventListener('submit',async event=>{\n    event.preventDefault();if(busy)return;\n    const input=document.getElementById('led-buyer-question'),question=input.value.trim();if(!question)return;\n    const status=document.getElementById('led-buyer-status'),submit=document.getElementById('led-buyer-send');\n    messages.append(element('p',question,'led-buyer-question'));input.value='';let ids=matchBuyerTopics(question,data.buyerGuide.topics);\n    if(!ids.length&&!/\\b[^\\s@]+@[^\\s@]+\\.[^\\s@]+\\b/.test(question)&&endpoint&&!aiUnavailable){\n      busy=true;submit.disabled=true;status.textContent='Finding the relevant buying guidance…';\n      const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),16000);\n      try{\n        const body=new FormData();body.set('quote_action','buyer-help');body.set('help_question',question);body.set('geometry',getState().geometry);\n        const response=await fetch(endpoint,{method:'POST',body,credentials:'same-origin',headers:{'X-Simworx-Buyer-Help':'1'},signal:controller.signal});const result=await response.json();\n        if(response.ok&&result.ok){ids=result.topicIds.filter(id=>data.buyerGuide.topics.some(topic=>topic.id===id&&id!=='unknown'));aiUnavailable=!result.ai;mode=result.ai?'AI-assisted topic matching':'Built-in answers';}\n      }catch{/* Approved local guidance remains available when the service is offline. */}finally{clearTimeout(timer);busy=false;submit.disabled=false;status.textContent='';document.getElementById('led-buyer-mode').textContent=mode;}\n    }\n    if(!ids.length)ids=['unknown'];ids.slice(0,2).forEach(addAnswer);\n    while(messages.children.length>24)messages.firstElementChild.remove();\n  });\n  function openComparison(){comparison.showModal();drawComparison();}\n  const compare=document.getElementById('led-pitch-compare');compare.disabled=false;compare.addEventListener('click',openComparison);\n  document.getElementById('led-pitch-close').addEventListener('click',()=>comparison.close());\n  function drawComparison(){\n    const root=document.getElementById('led-pitch-comparisons');root.replaceChildren();\n    for(const pitch of data.pixelPitches.filter(pitch=>pitch.mm&&pitch.geometries.includes('curved'))){\n      const figure=document.createElement('figure'),canvas=document.createElement('canvas');canvas.width=260;canvas.height=140;canvas.setAttribute('aria-label',`${pitch.label}: illustrative relative pixel spacing`);canvas.setAttribute('role','img');\n      const c=canvas.getContext('2d');if(!c)continue;c.fillStyle='#18212a';c.fillRect(0,0,260,140);\n      const spacing=pitch.mm*4.2;\n      for(let y=spacing/2;y\u003c140;y+=spacing)for(let x=spacing/2;x\u003c260;x+=spacing){const sky=y\u003c65;const runway=Math.abs(x-130)\u003c(y-42)*.63;c.fillStyle=sky?'#aabfcb':runway?'#c9cdd0':'#667773';c.fillRect(x-spacing*.36,y-spacing*.36,spacing*.72,spacing*.72);}\n      figure.append(canvas,element('figcaption',pitch.label));root.append(figure);\n    }\n  }\n  return {refresh:()=>{if(dialog.open&&messages.children.length===1)showStep();}};\n}\n", "protection": "(() => {\n  'use strict';\n  const forms = [...document.querySelectorAll('form[data-antispam]')];\n  if (!forms.length) return;\n\n  const states = new Map();\n  for (const form of forms) {\n    const status = document.createElement('p');\n    status.className = 'sw-form-verification-status full';\n    status.setAttribute('role', 'status');\n    status.setAttribute('aria-live', 'polite');\n    const widget = document.createElement('div');\n    widget.className = 'sw-form-verification full';\n    const trap = document.createElement('div');\n    trap.className = 'sw-form-honeypot';\n    trap.hidden = true;\n    const input = document.createElement('input');\n    input.name = 'simworx_website';\n    input.type = 'text';\n    input.tabIndex = -1;\n    input.autocomplete = 'off';\n    input.setAttribute('aria-label', 'Leave this field empty');\n    trap.append(input);\n    const button = form.querySelector('[type=\"submit\"], button:not([type])');\n    // Keep verification outside the existing submit row so its button and\n    // privacy text retain their layout, including in forms with nested buttons.\n    let anchor = button;\n    while (anchor && anchor.parentNode !== form) anchor = anchor.parentNode;\n    form.insertBefore(trap, anchor);\n    form.insertBefore(widget, anchor);\n    form.insertBefore(status, anchor);\n    const state = { widget, status, id: null, verified: false };\n    states.set(form, state);\n    status.textContent = 'Loading spam protection…';\n\n    // Run before existing submission listeners. No enquiry reaches the handler\n    // until Turnstile supplies a token; the handler must still verify it itself.\n    form.addEventListener('submit', event => {\n      if (state.id === null || !state.verified || !window.turnstile?.getResponse(state.id)) {\n        event.preventDefault();\n        event.stopImmediatePropagation();\n        status.textContent = 'Please complete the verification before sending your enquiry.';\n      }\n    }, true);\n    const reset = () => {\n      state.verified = false;\n      if (state.id !== null && window.turnstile) window.turnstile.reset(state.id);\n    };\n    form.addEventListener('reset', reset);\n    // The existing AJAX handler signals completion on success and failure. Tokens\n    // are single-use, so renew after every attempt without clearing entered text.\n    form.addEventListener('simworx:submission-complete', reset);\n  }\n\n  const render = () => {\n    for (const [form, state] of states) {\n      const sitekey = form.dataset.turnstileSitekey;\n      const action = form.dataset.antispamAction;\n      if (!sitekey || !action) {\n        state.status.textContent = 'Enquiries are temporarily unavailable. Please email us directly.';\n        continue;\n      }\n      try {\n        state.id = window.turnstile.render(state.widget, {\n          sitekey,\n          action,\n          theme: 'auto',\n          ...(form.dataset.turnstileSize === 'compact' ? {size: 'compact'} : {}),\n          'response-field-name': 'cf-turnstile-response',\n          callback: () => {\n            state.verified = true;\n            state.status.textContent = '';\n          },\n          'expired-callback': () => {\n            state.verified = false;\n            state.status.textContent = 'Verification expired. Please verify again before sending.';\n            if (state.id !== null) window.turnstile.reset(state.id);\n          },\n          'error-callback': () => {\n            state.verified = false;\n            state.status.textContent = 'Verification could not load. Please retry or email us directly.';\n          },\n        });\n      } catch {\n        state.status.textContent = 'Verification could not load. Please retry or email us directly.';\n      }\n    }\n  };\n  if (window.turnstile) {\n    render();\n  } else {\n    // Load only on protected forms; other pages make no CAPTCHA requests.\n    window.simworxTurnstileReady = render;\n    const script = document.createElement('script');\n    script.src = 'https://challenges.cloudflare.com/turnstile/v0/api.js?onload=simworxTurnstileReady&render=explicit';\n    script.async = true;\n    script.onerror = () => {\n      for (const state of states.values()) {\n        state.status.textContent = 'Verification could not load. Please retry or email us directly.';\n      }\n    };\n    document.head.append(script);\n  }\n})();\n", "options": "import {formatArea} from './units.js?v=16';\nimport {optionPrice} from './pricing.js?v=16';\nimport {moduleLayout} from './geometry.js?v=16';\n\n/** Visible choices backed by the same catalogue/state as the quote, without duplicate pricing rules. */\nexport function createOptionControls(container,data,onChange) {\n  for(const group of data.optionGroups){\n    const fieldset=document.createElement('fieldset');fieldset.id=`led-${group.key}`;\n    fieldset.className=`led-panel led-option-group${group.wide?' led-option-wide':''}`;\n    fieldset.dataset.ledChoices=group.key;\n    const legend=document.createElement('legend');legend.textContent=group.title;\n    const help=document.createElement('p');help.className='led-option-help';help.id=`led-${group.key}-help`;help.textContent=group.help;\n    fieldset.setAttribute('aria-describedby',help.id);fieldset.append(legend,help);\n    const choices=document.createElement('div');choices.className='led-choice-list';\n    const options=group.type==='checkbox'?data[group.collection].filter(option=>option.id===group.on):data[group.collection];\n    for(const option of options){\n      const label=document.createElement('label');label.className='led-option-choice';\n      const input=document.createElement('input');input.type=group.type;input.name=`led-option-${group.key}`;\n      input.value=option.id;input.dataset.ledChoice=group.key;input.id=`led-choice-${group.key}-${option.id}`;\n      input.addEventListener('change',()=>onChange(group.key,group.type==='checkbox'?(input.checked?group.on:group.off):input.value));\n      const description=document.createElement('span');description.className='led-option-description';\n      const title=document.createElement('strong');title.textContent=group.type==='checkbox'?group.label:option.label;\n      description.append(title);\n      if(option.description){const text=document.createElement('small');text.textContent=option.description;description.append(text);}\n      const price=document.createElement('span');price.className='led-option-price';price.dataset.optionPrice=option.id;\n      label.append(input,description,price);choices.append(label);\n      if(group.key==='pixelPitch'){\n        const rate=document.createElement('small');rate.className='led-option-rate';rate.dataset.optionUnitRate=option.id;\n        const area=document.createElement('small');area.dataset.optionArea=option.id;description.append(rate,area);\n      }\n    }\n    fieldset.append(choices);\n    if(group.key==='pixelPitch'){\n      const compare=document.createElement('button');compare.id='led-pitch-compare';compare.type='button';compare.className='led-profile-link';compare.textContent='Which Pixel Pitch? Compare the difference';compare.disabled=true;fieldset.append(compare);\n      const guidance=document.createElement('p');guidance.id='led-pitch-guidance';guidance.className='led-guidance';fieldset.append(guidance);\n    }\n    if(group.key==='hardware'){\n      const description=document.createElement('p');description.id='led-hardware-description';description.className='led-option-help';\n      const title=document.createElement('h3');title.className='led-equipment-title';title.id='led-equipment-heading';\n      const equipment=document.createElement('ul');equipment.id='led-equipment-list';equipment.className='led-included-equipment';\n      const note=document.createElement('p');note.className='led-help';note.textContent='The list below identifies operating requirements. Final supply scope and compatibility are confirmed in the quotation.';\n      fieldset.append(description,title,equipment,note);\n    }\n    if(group.key==='spares'){\n      const custom=document.createElement('div');custom.className='led-field';custom.id='led-custom-spares';custom.hidden=true;\n      const label=document.createElement('label');label.htmlFor='led-customSpares';label.textContent='Requested spare percentage';\n      const input=document.createElement('input');input.id='led-customSpares';input.type='number';input.min='0';input.max='100';input.step='0.5';input.dataset.ledNumber='customSpares';\n      const note=document.createElement('p');note.className='led-help';note.textContent='Custom spares are priced with the formal quotation.';\n      custom.append(label,input,note);fieldset.append(custom);\n    }\n    (group.key==='pixelPitch'?document.getElementById('led-pitch-options')||container:container).append(fieldset);\n  }\n  return (state,unit='metric')=>{\n    const money=value=>new Intl.NumberFormat('en-GB',{style:'currency',currency:state.currency,minimumFractionDigits:0,maximumFractionDigits:2}).format(value);\n    const unitMoney=value=>new Intl.NumberFormat('en-GB',{style:'currency',currency:state.currency,minimumFractionDigits:0,maximumFractionDigits:2}).format(value);\n    for(const group of data.optionGroups){\n      const fieldset=document.getElementById(`led-${group.key}`);\n      for(const input of fieldset.querySelectorAll('[data-led-choice]')){\n        if(group.key==='pixelPitch'){\n          const option=data.pixelPitches.find(option=>option.id===input.value);\n          input.closest('label').hidden=!option.geometries.includes(state.geometry)&&state.pixelPitch!==input.value;\n        }\n        input.checked=state[group.key]===input.value;\n        const item=optionPrice(state,data,group,input.value),price=input.closest('label').querySelector('[data-option-price]');\n        const unitRate=input.closest('label').querySelector('[data-option-unit-rate]');\n        if(unitRate)unitRate.textContent=item?.amount!==null&&item?.unitAmount?`${state.currency!==data.pricing.baseCurrency?'≈ ':''}${unitMoney(item.unitAmount)} / module · ${item.quantity} module