reshOptions?.(state);}\n}\nfunction render(force=false){\n  const spec=specification(state,data,countries,lengthUnit),d=spec.dimensions;\n  for(const input of document.querySelectorAll('[data-led-number]')){\n    const key=input.dataset.ledNumber;\n    if(force||document.activeElement!==input)input.value=inputNumber(key,state[key]);\n    const range=document.querySelector(`[data-led-range=\"${key}\"]`),factor=lengthKeys.has(key)?lengthFactor(lengthUnit):1;\n    if(lengthKeys.has(key)){\n      input.min=(key==='diameter'||key==='viewableHeight'||key==='overallHeight'||['simulatorWidth','simulatorDepth','simulatorHeight'].includes(key) ? .1 : key==='simulatorX'||key==='simulatorZ'?-50:0)*factor;\n      input.max=(['diameter','viewableHeight','overallHeight'].includes(key)?1000:50)*factor;input.step='any';\n      const suffix=input.closest('.led-dimension')?.querySelector('.led-control-head>span');if(suffix)suffix.textContent=lengthSymbol(lengthUnit);\n    }\n    if(range){\n      const bounds=data.previewRanges[key]||{min:Number(range.min),max:Number(range.max)};\n      range.min=Math.min(bounds.min,state[key])*factor;range.max=Math.max(bounds.max,state[key])*factor;range.step=(key==='diameter' ? .1 : ['horizontalFov','upperCoverage','lowerCoverage','simulatorYaw'].includes(key)?1:.05)*factor;\n      if(key==='overallHeight'&&state.geometry==='curved')range.min=state.viewableHeight*factor;\n      if(key==='viewableHeight'&&state.geometry==='curved'){\n        range.min=d.moduleLayout.moduleHeight*factor;range.max=state.overallHeight*factor;\n        range.step=d.moduleLayout.moduleHeight*factor;input.min=d.moduleLayout.moduleHeight*factor;\n      }\n      range.value=state[key]*factor;range.setAttribute('aria-valuetext',`${number(state[key]*factor)}${key.includes('Coverage')?' percent':['horizontalFov','simulatorYaw'].includes(key)?' degrees':lengthUnit==='imperial'?' feet':' metres'}`);\n    }\n  }\n  for(const select of document.querySelectorAll('[data-led-select]')