.version===1?draft.configuration:data.defaults,data);}catch{state=normaliseConfiguration(data.defaults,data);}\n    lengthUnit=draft?.lengthUnit==='imperial'?'imperial':'metric';byId('led-dimension-unit').value=lengthUnit;\n    byId('led-dimension-unit').addEventListener('change',event=>{lengthUnit=event.target.value;markChanged();render(true);save();});\n    // Apply the new euro default once to older reviews; retain later explicit currency choices.\n    if(draft&&draft.pricingFlowVersion!==2)state.currency=data.defaults.currency;\n    if(state.country&&!countries.some(country=>country.code===state.country))state.country='';\n    const requestedGeometry=new URLSearchParams(location.search).get('geometry');\n    if(['curved','hemispherical'].includes(requestedGeometry))state=normaliseConfiguration({...state,geometry:requestedGeometry},data);\n    for(const [key,collection] of Object.entries(collections))fillSelect(byId(`led-${key}`),data[collection],key==='application'?'Select application':'');\n    refreshOptions=createOptionControls(byId('led-option-groups'),data,change);\n    fillSelect(byId('led-country'),countries.map(country=>({id:country.code,label:country.name})),'Select installation country');\n    fillSelect(byId('led-currency'),[{id:'EUR',label:'EUR — Euro'},{id:'GBP',label:'GBP — Pound sterling'},{id:'USD',label:'USD — US dollar'}]);\n    let identity={};try{identity=JSON.parse(localStorage.getItem('simworxLedOfflineIdentityV1')||'{}')||{};}catch{}\n    const saved=draft?.customer||{...identity,organisation:identity.company||''};\n    for(const key of ['name','organisation','email','phone','project','comments'])if(typeof saved[key]==='string')form.elements[key].value=saved[key];\n    document.querySelectorAll('[data-led-number]').forEach(input=>{\n      input.addEventListener('input',()=>change(input.dataset.ledNumber,inputValue(input.dataset.ledNumber,input.value)));\n      input.addEventListener('blur',()=>{input.value=inputNumber(input.dataset.ledNumber,state[input.dataset.ledNumber]);});\n    });\n    document.querySelectorAll('[data-led-range]').forEach(input=>input.addEventListener('input',()=>change(input.dataset.ledRange,inputValue(input.dataset.ledRange,input.value))));\n    document.querySelectorAll('[data-led-select]').forEach(input=>input.addEventListener('change',()=>change(input.dataset.ledSelect,input.value)));\n    document.querySelectorAll('[data-led-text]').forEach(input=>input.addEventListener('input',()=>change(input.dataset.ledText,input.value)));\n    document.querySelectorAll('[data-led-toggle]').forEach(input=>input.addEventListener('change',()=>change(input.dataset.ledToggle,input.checked)));\n    document.querySelectorAll('[name=led-geometry]').forEach(input=>input.addEventListener('change',()=>{if(input.checked)change('geometry',input.value);}));\n    byId('led-full-dome').addEventListener('click',()=>{state=normaliseConfiguration({...state,...data.fullDomePreset},data);markChanged();render();save();});\n    form.addEventListener('input',()=>{markChanged();save();});\n    document.querySelectorAll('[data-viewer]').forEach(button=>{button.disabled=true;button.addEventListener('click',()=>viewer?.[button.dataset.viewer]());});\n    canvas.addEventListener('led:viewer-unavailable',()=>{viewerStatus.hidden=false;viewerStatus.textContent='The 3D preview paused. Your specification is retained and can still be submitted.';});\n    quoteActions=createQuoteActions({form,getConfiguration:()=>({...state}),getCustomer:customer,onSave:save,captureViews:async()=>{await loadViewer();return viewer?.captureViews()||[];}});\n    render();\n    createBuyerHelp({data,getState:()=>({...state}),getPricing:()=>specification(state,data,countries,lengthUnit).pricing,endpoint:document.documentElement.dataset.ledQuotePreview==='offline'?null:form.action});\n    createProfiles({getConfiguration:()=>({...state}),getUnit:()=>lengthUnit,getCustomer:customer,defaultSimulator:()=>state.cockpit||optionLabel(data,'simulatorReferences',state.simulatorType),onRestore:profile=>{\n      try{state=normaliseConfiguration(profile.configuration,data);lengthUnit=profile.lengthUnit==='imperial'?'imperial':'metric';byId('led-dimension-unit').value=lengthUnit;form.elements.email.value=profile.email;form.elements.name.value=profile.username;form.elements.organisation.value=profile.company||'';markChanged();render();save();}catch{byId('led-profile-status').textContent='Saved configuration needs review. Please contact Simworx.';}\n    }});\n    save();\n    if('ResizeObserver'in window)new ResizeObserver(entries=>document.documentElement.style.setProperty('--led-estimate-height',`${entries[0].target.getBoundingClientRect().height}px`)).observe(document.querySelector('.led-estimate-bar'));\n    window.SimworxLED=Object.freeze({snapshot:()=>({configuration:{...state},lengthUnit,...specification(state,data,countries,lengthUnit)}),viewerSnapshot:()=>viewer?.snapshot()||null});\n    if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>{if(entries.some(entry=>entry.isIntersecting)){observer.disconnect();loadViewer();}},{rootMargin:'200px'});observer.observe(canvas);}else loadViewer();\n  }catch(error){controlError.textContent='Configuration data could not load. Please reload the page or contact Simworx.';viewerStatus.textContent='Preview unavailable. Please contact Simworx with your screen requirements.';button.disabled=true;}\n}\ninitialise();\n"},moduleUrls={};
function moduleFile(key,dependencies=[]){
 let source=sources[key];
 for(const [path,dependency] of dependencies)source=source.split("'"+path+"'").join(JSON.stringify(moduleUrls[dependency]));
 moduleUrls[key]=URL.createObjectURL(new Blob([source],{type:'text/javascript'}));
}
